  1	method mergeSimple(a1: seq<int>, a2: seq<int>, start: int, end: int, b: array<int>)
  2	  modifies b
  3	  requires sorted_seq(a1)
  4	  requires sorted_seq(a2)
  5	  requires 0 <= start <= end <= b.Length
  6	  requires |a1| +  |a2| == end - start + 1
  7	  ensures sorted_slice(b, start, end)
  8	{
  9	  var a1Pos := 0;
 10	  var a2Pos := 0;
 11	  var k := start;
 12	
 13	  while k < end
 14	    invariant (0 <= k && k <= end)
 15	    invariant sorted_slice(b, start, k)
 16	    invariant (|a1| - a1Pos) + (|a2| - a2Pos) == end - k + 1
 17	    invariant 0 <= a1Pos <= |a1|
 18	    invariant 0 <= a2Pos <= |a2|
 19	    invariant forall i :: start <= i < k && a1Pos < |a1| ==> b[i] <= a1[a1Pos]
 20	    invariant forall i :: start <= i < k && a2Pos < |a2| ==> b[i] <= a2[a2Pos]
 21	  {
 22	    if a1Pos < |a1| && a2Pos < |a2| && a1[a1Pos] <= a2[a2Pos] {
 23	      b[k] := a1[a1Pos];
 24	      a1Pos := a1Pos + 1;
 25	    } else if a1Pos < |a1| && a2Pos < |a2| && a1[a1Pos] > a2[a2Pos] {
 26	      b[k] := a2[a2Pos];
 27	      a2Pos := a2Pos + 1;
 28	    } else if a1Pos < |a1| {
 29	      assert(a2Pos >= |a2|);
 30	      b[k] := a1[a1Pos];
 31	      a1Pos := a1Pos + 1;
 32	    } else {
 33	      assert(a1Pos >= |a1|);
 34	      b[k] := a2[a2Pos];
 35	      a2Pos := a2Pos + 1;
 36	    }
 37	    k := k + 1;
 38	  }
 39	}
