 41	method merge(a1: seq<int>, a2: seq<int>, start: int, end: int, b: array<int>)
 42	  modifies b
 43	  requires sorted_seq(a1)
 44	  requires sorted_seq(a2)
 45	  requires end - start == |a1| + |a2|
 46	  requires 0 <= start < end < |a1| && end <= |a2| < b.Length
 47	  requires end < |a1| && end < |a2|
 48	  ensures sorted_slice(b, start, end)
 49	  requires b.Length == |a2| + |a1|
 50	  ensures merged(a1, a2, b, start, end)
 51	{
 52	  assert forall xs : seq<int> :: xs[0..|xs|] == xs;
 53	  assert forall xs : seq<int>, a,b : int :: 0 <= a < b < |xs| ==> xs[a..b+1] == xs[a..b] + [xs[b]];
 54	  var a1Pos := 0;
 55	  var a2Pos := 0;
 56	  var k := start;
 57	  while k < end
 58	    invariant (0 <= k && k <= end)
 59	    invariant sorted_slice(b, start, k)
 60	    invariant (|a1| - a1Pos) + (|a2| - a2Pos) == end - k
 61	    invariant 0 <= a1Pos <= |a1|
 62	    invariant 0 <= a2Pos <= |a2|
 63	    invariant forall i :: start <= i < k && a1Pos < |a1| ==> b[i] <= a1[a1Pos]
 64	    invariant forall i :: start <= i < k && a2Pos < |a2| ==> b[i] <= a2[a2Pos]
 65	    invariant merged(a1[0..a1Pos], a2[0..a2Pos], b, start, k)
 66	  {
 67	    if a1Pos < |a1| && a2Pos < |a2| && a1[a1Pos] <= a2[a2Pos] {
 68	      b[k] := a1[a1Pos];
 69	      a1Pos := a1Pos + 1;
 70	    } else if a1Pos < |a1| && a2Pos < |a2| && a1[a1Pos] > a2[a2Pos] {
 71	      b[k] := a2[a2Pos];
 72	      a2Pos := a2Pos + 1;
 73	    } else if a1Pos < |a1| {
 74	      assert(a2Pos >= |a2|);
 75	      b[k] := a1[a1Pos];
 76	      a1Pos := a1Pos + 1;
 77	    } else {
 78	      assert(a1Pos >= |a1|);
 79	      b[k] := a2[a2Pos];
 80	      a2Pos := a2Pos + 1;
 81	    }
 82	    k := k + 1;
 83	  }
 84	}
