 94	predicate sorted_slice(a: array<int>, start: int, end: int)
 95	  requires 0 <= start <= end <= a.Length
 96	  reads a
 97	{
 98	  forall i, j :: start <= i <= j < end ==> a[i] <= a[j]
 99	}
